// --- PARAMETERS ---
// Set in the dock: Red (c1) and White (c2) for the classic effect
vec3 c1 = u_col1;
vec3 c2 = u_col2;

// --- SPIRAL SETTINGS ---
// Coils: how many stripes you see in a cross-section of the tube
float coils = 6.0;

// Twists: how many full turns the spiral makes along the whole torus
// It must be an integer to keep the texture from being cut at the joint
float twists = 40.0;

// --- COMPUTATION ---
// The trick is to add U and V, each multiplied.
// (u * twists) pushes the texture along the path
// (v * coils) wraps the texture around the tube
// Adding the two gives a diagonal line (helix/spiral)
float pos = (u * twists) + (v * coils);

// --- SHARP STRIPES ---
// fract(pos) creates a sawtooth from 0.0 to 1.0, repeated
// step(0.5, ...) cuts the value sharply: below 0.5 it is 0, above it is 1.
float stripe = step(0.5, fract(pos));

// Gives the color (no blending)
return mix(c1, c2, stripe);
